def merge_intervals(intervals):
    if not intervals:
        return []

    # 開始点でソート
    intervals = sorted(intervals, key=lambda x: x[0])

    merged = []
    for start, end in intervals:
        if not merged or start > merged[-1][1]:
            # 重ならない（端点が接する場合は重なる扱いなので start > end のみ新規追加）
            merged.append([start, end])
        else:
            # 重なる場合は終点を拡張
            if end > merged[-1][1]:
                merged[-1][1] = end

    return merged
