def calculate(s: str) -> int:
    s = s.replace(" ", "")
    n = len(s)
    i = 0

    def parse_expr():
        nonlocal i
        val = parse_term()
        while i < n and s[i] in "+-":
            op = s[i]
            i += 1
            rhs = parse_term()
            if op == "+":
                val += rhs
            else:
                val -= rhs
        return val

    def parse_term():
        nonlocal i
        val = parse_factor()
        while i < n and s[i] in "*/":
            op = s[i]
            i += 1
            rhs = parse_factor()
            if op == "*":
                val *= rhs
            else:
                # 0方向への切り捨て
                if val >= 0 and rhs >= 0:
                    val //= rhs
                elif val >= 0 and rhs < 0:
                    val = -(val // (-rhs))
                elif val < 0 and rhs >= 0:
                    val = -((-val) // rhs)
                else:
                    val = (-val) // (-rhs)
        return val

    def parse_factor():
        nonlocal i
        sign = 1
        while i < n and s[i] in "+-":
            if s[i] == "-":
                sign = -sign
            i += 1
        if i < n and s[i] == "(":
            i += 1
            val = parse_expr()
            if i < n and s[i] == ")":
                i += 1
            return sign * val
        # 数値
        num = 0
        while i < n and s[i].isdigit():
            num = num * 10 + int(s[i])
            i += 1
        return sign * num

    return parse_expr()
```

