def sliding_median(nums, k):
    n = len(nums)
    if k <= 0 or k > n:
        return []

    vals = sorted(set(nums))
    m = len(vals)
    index = {v: i + 1 for i, v in enumerate(vals)}

    bit = [0] * (m + 1)

    def add(i, delta):
        while i <= m:
            bit[i] += delta
            i += i & -i

    def kth(k):
        pos = 0
        step = 1 << (m.bit_length() - 1)
        while step:
            nxt = pos + step
            if nxt <= m and bit[nxt] < k:
                pos = nxt
                k -= bit[nxt]
            step >>= 1
        return pos + 1

    for j in range(k):
        add(index[nums[j]], 1)

    result = []
    half = k // 2

    for i in range(n - k + 1):
        if k % 2 == 1:
            v = vals[kth(half + 1) - 1]
            result.append(float(v))
        else:
            v1 = vals[kth(half) - 1]
            v2 = vals[kth(half + 1) - 1]
            result.append((float(v1) + float(v2)) / 2.0)

        if i + k < n:
            add(index[nums[i]], -1)
            add(index[nums[i + k]], 1)

    return result
